class Animal { name = 'animal'; }
class Dog extends Animal { breed = 'lab'; }

const dogs: Dog[] = [new Dog()];
// const animals: Animal[] = dogs; // error under strict — invariant

const readonlyDogs: readonly Dog[] = dogs;
const readonlyAnimals: readonly Animal[] = readonlyDogs; // OK — covariant

type Handler<T> = (arg: T) => void;

const logAnimal: Handler<Animal> = (a) => console.log(a.name);
const logDog: Handler<Dog> = logAnimal; // OK — contravariant param

// const bad: Handler<Animal> = (d: Dog) => console.log(d.breed);
// error — Handler<Dog> not assignable to Handler<Animal>

interface Producer<out T> {
  get(): T;
}

interface Consumer<in T> {
  accept(value: T): void;
}

const dogProducer: Producer<Dog> = { get: () => new Dog() };
const animalProducer: Producer<Animal> = dogProducer; // covariant out

const dogs: Dog[] = [new Dog()];
const animals = dogs as Animal[];
animals.push(new Animal()); // runtime: Dog[] contains Animal instance
const d = dogs[1];
console.log(d.breed); // undefined — variance violation via cast
